#!/usr/bin/env node
/**
 * Bundle the browser bridge host to `dist/bridge.js`.
 *
 * Served at `/__forge/bridge.js` and injected as a classic <script src> ahead
 * of all app code, so it must be a self-contained IIFE with no imports and no
 * module semantics — a `type="module"` script is deferred, which would let app
 * code run before `window.__bridge` exists.
 *
 * Built at `npm run build` so an npm-installed user never needs a build step.
 */
import { build } from 'esbuild';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..');

const result = await build({
  entryPoints: [join(repoRoot, 'src/bridge/hosts/browser/entry.ts')],
  outfile: join(repoRoot, 'dist/bridge.js'),
  bundle: true,
  format: 'iife',
  platform: 'browser',
  target: ['es2020'],
  sourcemap: false,
  legalComments: 'none',
  banner: { js: '/* forge-sim browser bridge — generated by scripts/build-bridge-bundle.mjs. Do not edit. */' },
  metafile: true,
});

const out = result.metafile.outputs[Object.keys(result.metafile.outputs)[0]];
console.log(`[build-bridge-bundle] dist/bridge.js — ${(out.bytes / 1024).toFixed(1)} kB`);
